const [cards, setCards] = useState(initialTasks);

<Kanban
  title="Sprint 14"
  columns={[
    { id: "todo", title: "To do" },
    { id: "doing", title: "In progress", limit: 3, tone: "accent" },
    { id: "done", title: "Done", tone: "success" },
  ]}
  cards={cards}
  onMove={({ cardId, toColumnId, index }) => setCards((cs) => moveCard(cs, cardId, toColumnId, index))}
  renderCard={(t) => <><b>{t.title}</b><small>{t.owner}</small></>}
  onCardClick={(t) => openTask(t.id)}
  onAddCard={(columnId, title) => createTask({ columnId, title })}
  loading={isLoading}
/>
